struct State { int count = 0; std::string filter = "all"; };
using Action = std::variant<Increment, SetFilter>;
State reduce(const State& s, const Action& a) {
  return std::visit(overloaded{
      [&](const Increment&) { auto n = s; ++n.count; return n; },
      [&](const SetFilter& f) { auto n = s; n.filter = f.value; return n; },
    }, a);
}
